@router.post('/{task_id}/transition')
async def transition_task(task_id: str, req: TransitionRequest):
    """手动状态转换。"""
    engine = _get_engine()
    task = engine.db.get_task(task_id)
    if not task:
        raise HTTPException(404, '任务不存在: %s' % task_id)
    current = task.get('status')
    target = req.status
    ok = engine.db.cas_transition(
        task_id, current, target, message=req.message)
    if not ok:
        raise HTTPException(
            409, '状态转换失败: 当前状态 %s，无法转换至 %s' % (current, target))
    return {'ok': True, 'task_id': task_id,
            'from': current, 'to': target}


@router.post('/{task_id}/progress')
async def update_progress(task_id: str, req: ProgressRequest):
    """更新任务进度。"""
    engine = _get_engine()
    ok = engine.update_progress(task_id, req.progress, message=req.message)
    if not ok:
        raise HTTPException(400, '进度更新失败（任务不存在或非 running 状态）')
    return {'ok': True, 'task_id': task_id, 'progress': req.progress}
